@dataclasses.dataclass
class Item:
    """One synced thing, with its value in three places (None = absent)."""

    kind: str
    key: str
    base: str | None  # in the list as of this machine's last sync
    target: str | None  # in the list now
    machine: str | None  # on this machine now
    choice: str = ""  # answer for a local change / conflict: k, d, i or s

    @property
    def status(self) -> str:
        """Who changed it since the last sync: same, remote (the list), local, or conflict."""
        if self.machine == self.target:
            return "same"
        if self.machine == self.base:
            return "remote"
        if self.target == self.base:
            return "local"
        return "conflict"


@app.command()
def sync(
    *,
    pull: Annotated[
        bool, typer.Option(help="git pull --rebase the repo first (offers to commit uncommitted edits).")
    ] = True,
    push: Annotated[bool, typer.Option(help="git push after committing.")] = True,
    message: Annotated[str, typer.Option("--message", "-m", help="Commit message.")] = "os sync: update machine setup",
    dry_run: Annotated[bool, typer.Option("--dry-run", help="Show what would happen; ask and change nothing.")] = False,
    yes: Annotated[bool, typer.Option("--yes", "-y", help="No questions: apply the list, skip local changes.")] = False,
) -> None:
    """Make this machine and .os/machine.toml the same, in both directions.

    Asks what to do with each change made on this machine (keep = save it to the list,
    discard = undo it here), applies the changes that came from the list, then commits and
    pushes .os/.
    """
    _check_omarchy()
    if pull:
        _pull(dry_run=dry_run, yes=yes)
    base_commit = _last_synced()
    target = tomllib.loads(MACHINE_LIST.read_text())
    base = _base_list(base_commit)
    items = _items(target, base, base_commit)
    if base is None:
        typer.echo("First sync on this machine: every difference is a question, nothing is removed unasked.")
    pending = [item for item in items if item.status in ("local", "conflict")]
    if dry_run:
        _preview(pending, [item for item in items if item.status == "remote"], target, first=base is None)
        if shutil.which("secret-tool") and _stored_password() is None:
            typer.echo("\nWould offer to store the 1Password master password (none in the keyring yet).")
        return

    if pending and yes:
        typer.echo(f"\nSkipped {len(pending)} change(s) on this machine (they need an answer; run without --yes):")
        for item in pending:
            typer.echo(f"  {_question(item, first=base is None)[0]}")
    elif pending:
        _ask_all(pending, first=base is None)
    kept = [item for item in pending if item.choice in ("k", "i")]
    if kept:
        _save_all(kept)

    changes = [item for item in items if item.status == "remote" or item.choice == "d"]
    applied, failed = _apply_confirmed(changes, target, yes=yes)
    pushed = _commit_and_push(message, push=push, yes=yes)
    # Recorded even when something failed to apply: the leftover then shows up as a question
    # on the next sync, instead of the machine staying on "first sync" for good.
    if applied:
        STATE.mkdir(parents=True, exist_ok=True)
        (STATE / "synced").write_text(f"{_out(['git', '-C', str(REPO), 'rev-parse', 'HEAD'])}\n")
    if not yes:
        _offer_pwd_store()
    if failed:
        typer.echo("\nThese did not apply (the next `os sync` asks what to do with them):", err=True)
        for line in failed:
            typer.echo(f"  {line}", err=True)
    if failed or not pushed:
        raise typer.Exit(1)


@app.command()
def save(
    things: Annotated[
        list[str] | None,
        typer.Argument(
            help="<kind>:<name>; kinds: package, plugin, webapp, file, setting, toggle, bar. None: all changes.",
        ),
    ] = None,
    *,
    dry_run: Annotated[bool, typer.Option("--dry-run", help="Show what would be saved; change nothing.")] = False,
) -> None:
    """Save this machine's changes to the list, asking nothing.

    With no names: every change made on this machine since its last sync (what `os sync` would
    ask about), each saved as if answered "keep". With names: only those, eg right after
    installing a package or editing a tracked file (a new file path starts being tracked).
    Anything the list changed since this machine's last sync is left for `os sync` to settle.
    Only writes .os/ (no pull, commit or push); the next `os sync` commits and pushes it.
    """
    _check_omarchy()
    target = tomllib.loads(MACHINE_LIST.read_text())
    if things:
        items, problems = _kept_items([_thing(thing, target) for thing in things], target)
    else:
        items, problems = _all_local_items(target)
    if problems:
        for line in problems:
            typer.echo(line, err=True)
        typer.echo("Nothing was saved.", err=True)
        raise typer.Exit(1)
    for item in items:
        action = "remove from" if item.machine is None else "add to" if item.target is None else "update in"
        typer.echo(f"{f'Would {action}' if dry_run else action.capitalize()} the list: {KINDS[item.kind]} {item.key}")
    if items and not dry_run:
        _save_all(items)
        typer.echo("Saved in .os/ (not committed); `os sync` commits and pushes it for the other machines.")


def _all_local_items(target: dict[str, Any]) -> tuple[list[Item], list[str]]:
    """Changes made on this machine only, and what blocks saving (conflicts: listed only)."""
    base_commit = _last_synced()
    base = _base_list(base_commit)
    if base is None:
        return [], ["This machine has never synced, so its changes can't be told from the list's; run `os sync`."]
    items = _items(target, base, base_commit)
    local = [item for item in items if item.status == "local"]
    for item in local:
        item.choice = "k"
    if not local:
        typer.echo("No changes on this machine to save.")
    # Changed both here and in the list since the last sync: saving this machine's version
    # would undo the other machine's change, so those stay a question for `os sync`.
    conflicts = [f"  {KINDS[item.kind]} {item.key}" for item in items if item.status == "conflict"]
    if conflicts:
        typer.echo("Left for `os sync` (changed here and in the list since the last sync):", err=True)
        for line in conflicts:
            typer.echo(line, err=True)
    return local, []


def _thing(thing: str, target: dict[str, Any]) -> tuple[str, str]:
    """Parse a `save` argument, `<kind>:<name>`, into (kind, key); exits on an invalid one."""
    kind, _, key = thing.partition(":")
    problem = ""
    if kind not in KINDS or not key:
        problem = f"use <kind>:<name>, with kind one of: {', '.join(KINDS)}"
    elif kind == "file":
        path = Path(key).expanduser()
        if path.is_absolute() and not path.is_relative_to(HOME):
            problem = "only files under $HOME can be tracked"
        else:
            key = str(path.relative_to(HOME)) if path.is_absolute() else key
            when = target.get("files", {}).get(key)
            if when and not _applies(when):
                problem = f'[files] has it for other machines only ("{when}")'
    elif kind == "setting" and key not in SETTINGS:
        problem = f"unknown setting (known: {', '.join(SETTINGS)})"
    elif kind == "toggle" and (key == "flags" or not (OMARCHY_PATH / "default/hypr/toggles" / f"{key}.lua").is_file()):
        problem = "no such Omarchy Hyprland toggle"
    elif key in target.get("ignore", {}).get(f"{kind}s", []):
        problem = "it is in [ignore]; take it out of there first"
    if problem:
        typer.echo(f"{thing}: {problem}.", err=True)
        raise typer.Exit(1)
    return kind, key


def _kept_items(keys: list[tuple[str, str]], target: dict[str, Any]) -> tuple[list[Item], list[str]]:
    """The named things that changed on this machine only, and the problems with the rest."""
    base_commit = _last_synced()
    base = _base_list(base_commit)
    target_values = _list_values(target, lambda path: _read(FILES / path))
    base_values = _list_values(base, lambda path: _git_show(base_commit or "", f".os/files/{path}")) if base else {}
    machine_values = _machine_values({key for key in keys if key[0] not in OPEN_KINDS}, listed=set(keys))
    items, problems = [], []
    for kind, key in dict.fromkeys(keys):
        values = [source.get((kind, key)) for source in (base_values, target_values, machine_values)]
        if kind == "file" and values[1] is None:
            values[0] = None  # not in the repo yet: nothing to compare with, just save it
        item = Item(kind, key, *values, choice="k")
        label = f"{KINDS[kind]} {key}"
        if item.machine is None and item.target is None:
            problems.append(f"{label}: not on this machine and not in the list (check the name).")
        elif item.machine is None and kind == "setting":
            problems.append(f"{label}: could not read it on this machine.")
        elif item.status == "same":
            typer.echo(f"{label}: already in the list.")
        elif item.status == "local":
            items.append(item)
        else:
            # Changed in the list since this machine's last sync (or it never synced): saving
            # this machine's version would undo that, so it stays a question for `os sync`.
            problems.append(f"{label}: the list has a version this machine has not synced; settle it with `os sync`.")
    return items, problems


def _check_omarchy() -> None:
    """Stop early if the Omarchy CLI is missing or has renamed a command this relies on."""
    if shutil.which("omarchy") is None:
        typer.echo("The `omarchy` command was not found; `os sync` needs Omarchy 4.", err=True)
        raise typer.Exit(1)
    routes = {command["route"] for command in json.loads(_out(["omarchy", "commands", "--json"]))["commands"]}
    missing = [route for route in REQUIRED_ROUTES if route not in routes]
    if missing:
        typer.echo("This Omarchy version lacks commands `os sync` uses (renamed in an update?):", err=True)
        for route in missing:
            typer.echo(f"  {route}", err=True)
        typer.echo("Nothing was changed. Update the command names in .os/cli.py.", err=True)
        raise typer.Exit(1)


def _pull(*, dry_run: bool, yes: bool) -> None:
    """Pull the repo. Uncommitted edits block a pull, so first offer to commit them (all)."""
    git = ["git", "-C", str(REPO)]
    edited = _out([*git, "status", "--short", "--untracked-files=no"])
    if edited:
        typer.echo(f"Uncommitted changes in the repo:\n{edited}")
        if dry_run:
            typer.echo("Dry run: not pulling; previewing against the list as it is here.\n")
            return
        typer.echo("To pull, these must be committed first (all of them, not only .os/).")
        if yes or not typer.confirm("Commit them and pull? (no = skip the pull, sync with the list as it is here)"):
            typer.echo("Skipped the pull.\n")
            return
        message = ""
        while not message:
            message = typer.prompt("Commit message").strip()
        commit = [*git, "commit", "-m", message]
        subprocess.run([*git, "add", "--update"], check=True)
        # Pre-commit hooks may auto-fix files and fail once; restage, retry.
        if subprocess.run(commit, check=False).returncode != 0:
            subprocess.run([*git, "add", "--update"], check=True)
            if subprocess.run(commit, check=False).returncode != 0:
                typer.echo("Commit failed (see the hook output above). Nothing was pulled.", err=True)
                raise typer.Exit(1)
    # --rebase, not --ff-only: local commits (eg the one just made) go on top of the pull.
    if subprocess.run([*git, "pull", "--rebase"], check=False).returncode != 0:
        if (REPO / ".git" / "rebase-merge").exists() or (REPO / ".git" / "rebase-apply").exists():
            subprocess.run([*git, "rebase", "--abort"], check=False)
        typer.echo("Pull failed (conflict with the remote?). Nothing was changed; your commits are kept.", err=True)
        typer.echo("Run `git pull --rebase` and resolve it, then `os sync` again.", err=True)
        raise typer.Exit(1)


def _last_synced() -> str | None:
    record = STATE / "synced"
    return record.read_text().strip() if record.exists() else None


def _base_list(commit: str | None) -> dict[str, Any] | None:
    """The list as of this machine's last sync; None when there is none (first sync)."""
    text = _git_show(commit, ".os/machine.toml") if commit else None
    return tomllib.loads(text) if text is not None else None


def _git_show(commit: str, path: str) -> str | None:
    result = subprocess.run(["git", "-C", str(REPO), "show", f"{commit}:{path}"], capture_output=True, check=False)
    return result.stdout.decode(errors="surrogateescape") if result.returncode == 0 else None


def _read(path: Path) -> str | None:
    return path.read_bytes().decode(errors="surrogateescape") if path.is_file() else None


def _out(cmd: list[str]) -> str:
    return subprocess.run(cmd, capture_output=True, text=True, check=True).stdout.strip()


def _run(cmd: list[str]) -> bool:
    typer.echo(f"$ {shlex.join(cmd)}")
    # `omarchy webapp remove` sends a desktop notification per app unless told not to.
    env = {**os.environ, "OMARCHY_REMOVE_NOTIFY": "false"}
    return subprocess.run(cmd, check=False, env=env).returncode == 0


@functools.cache
def _lspci() -> str:
    return _out(["lspci"])


def _applies(when: str) -> bool:
    """Whether a `[files]` entry is for this machine: "always" or "lspci:<text>"."""
    if when == "always":
        return True
    if when.startswith("lspci:"):
        return when.removeprefix("lspci:") in _lspci()
    typer.echo(f'Unknown [files] value "{when}" in .os/machine.toml (use "always" or "lspci:<text>").', err=True)
    raise typer.Exit(1)


def _items(target: dict[str, Any], base: dict[str, Any] | None, base_commit: str | None) -> list[Item]:
    """Everything worth comparing, in apply order, with its value in all three places."""
    target_values = _list_values(target, lambda path: _read(FILES / path))
    base_values = _list_values(base, lambda path: _git_show(base_commit or "", f".os/files/{path}")) if base else {}
    files = {("file", path) for path, when in target.get("files", {}).items() if _applies(when)}
    named = files | {key for key in target_values if key[0] not in OPEN_KINDS}
    known = target_values.keys() | base_values.keys()
    machine_values = _machine_values(named, listed=known)
    ignore = target.get("ignore", {})
    ignored = {("package", name) for name in ignore.get("packages", [])}
    ignored |= {("webapp", name) for name in ignore.get("webapps", [])}
    keys = named | {key for key in known | machine_values.keys() if key[0] in OPEN_KINDS}
    items = []
    for kind, key in sorted(keys - ignored, key=lambda key: (list(KINDS).index(key[0]), key[1].lower())):
        values = [source.get((kind, key)) for source in (base_values, target_values, machine_values)]
        if kind == "file" and values[1] is None:
            values[0] = None  # listed but not in the repo yet: nothing to compare with, just save it
        if base is not None and kind in ("setting", "toggle", "bar") and values[0] is None:
            # Added to the list since this machine's last sync: not a change made here, so the
            # list's value goes in the plan instead of becoming a question.
            values[0] = values[2]
        if kind == "setting" and values[2] is None:
            typer.echo(f"Could not read the current {key} (`{shlex.join(SETTINGS[key][0])}`); leaving it alone.")
            continue
        items.append(Item(kind, key, *values))
    return items


def _list_values(machine_list: dict[str, Any], read_file: Any) -> dict[tuple[str, str], str]:
    """Flatten a machine list into {(kind, key): value}; `read_file` reads a tracked file."""
    values: dict[tuple[str, str], str] = {}
    packages = machine_list.get("packages", {})
    for name in [*packages.get("pacman", []), *packages.get("aur", [])]:
        values["package", name] = "installed"
    for plugin, git in machine_list.get("plugins", {}).items():
        values["plugin", plugin] = git
    for name, url in machine_list.get("webapps", {}).items():
        values["webapp", name] = url
    for key, value in machine_list.get("settings", {}).items():
        if key not in SETTINGS:
            typer.echo(f'Unknown setting "{key}" in .os/machine.toml (known: {", ".join(SETTINGS)}).', err=True)
            raise typer.Exit(1)
        values["setting", key] = str(value)
    for key, value in machine_list.get("toggles", {}).items():
        if value not in ("on", "off"):
            typer.echo(f'Toggle "{key}" in .os/machine.toml must be "on" or "off".', err=True)
            raise typer.Exit(1)
        values["toggle", key] = value
    for key, value in machine_list.get("bar", {}).items():
        values["bar", key] = json.dumps(value)
    for path, when in machine_list.get("files", {}).items():
        content = read_file(path) if _applies(when) else None
        if content is not None:
            values["file", path] = content
    return values


def _machine_values(named: set[tuple[str, str]], *, listed: set[tuple[str, str]]) -> dict[tuple[str, str], str]:
    """State of this machine as {(kind, key): value}: `named` keys plus anything new here."""
    values: dict[tuple[str, str], str] = {}
    # New packages: installed by hand (explicit) and not part of Omarchy itself. Listed ones
    # count however they got installed, so one that arrived as a dependency isn't "missing".
    shipped = {
        line.strip()
        for packages_file in (OMARCHY_PATH / "install").glob("*.packages")
        for line in packages_file.read_text().splitlines()
    }
    candidates = (set(_out(["pacman", "-Qqe"]).split()) - shipped) | {key for kind, key in listed if kind == "package"}
    for name in candidates & set(_out(["pacman", "-Qq"]).split()):
        values["package", name] = "installed"
    for plugin in sorted(PLUGINS.iterdir()) if PLUGINS.is_dir() else []:
        if not (plugin / ".git").exists():
            continue  # not a git checkout of its own (eg a local clone made to edit)
        remote = ["git", "-C", str(plugin), "remote", "get-url", "origin"]
        result = subprocess.run(remote, capture_output=True, text=True, check=False)
        if result.returncode == 0:
            values["plugin", plugin.name] = result.stdout.strip()
    for desktop in sorted(APPLICATIONS.glob("*.desktop")):
        url = _webapp_url(desktop)
        if url:
            values["webapp", desktop.stem] = url
    for kind, key in named:
        if kind == "setting":
            result = subprocess.run(SETTINGS[key][0], capture_output=True, text=True, check=False)
            value = result.stdout.strip() if result.returncode == 0 and result.stdout.strip() else None
        elif kind == "toggle":
            enabled = subprocess.run([*TOGGLE, "enabled", key], capture_output=True, check=False)
            value = "on" if enabled.returncode == 0 else "off"
        elif kind == "bar":
            value = _bar_value(key)
        else:
            value = _read(HOME / key)
        if value is not None:
            values[kind, key] = value
    return values


def _bar_value(key: str) -> str | None:
    """A bar widget option on this machine (JSON text), read from Omarchy's shell.json."""
    widget_id, _, option = key.rpartition(".")
    shell = json.loads(SHELL_JSON.read_text()) if SHELL_JSON.is_file() else {}
    for section in shell.get("bar", {}).get("layout", {}).values():
        for widget in section:
            if widget.get("id") == widget_id and option in widget:
                return json.dumps(widget[option])
    return None


def _desktop_value(desktop: Path, key: str) -> str:
    prefix = f"{key}="
    lines = desktop.read_text(errors="replace").splitlines()
    return next((line.removeprefix(prefix) for line in lines if line.startswith(prefix)), "")


def _webapp_url(desktop: Path) -> str | None:
    """The URL a web app launcher opens, or None if the file isn't a plain web app launcher.

    Gives the same URL for launchers written by older Omarchy versions (bare URL) and current
    ones (quoted, `%` doubled, backslash escapes), so a URL survives a reinstall unchanged.
    """
    escapes = {"s": " ", "n": "\n", "t": "\t", "r": "\r"}
    # Desktop-file string escapes come off first, then the Exec quoting (the order a launcher
    # reads them in).
    value = re.sub(r"\\(.)", lambda match: escapes.get(match[1], match[1]), _desktop_value(desktop, "Exec"))
    command, _, argument = value.partition(" ")
    if command != "omarchy-launch-webapp" or not argument:
        return None
    quoted = re.match(r'"((?:[^"\\]|\\.)*)"', argument)
    if quoted:
        return re.sub(r"\\(.)", r"\1", quoted[1]).replace("%%", "%")
    return argument.split(" ")[0]


def _question(item: Item, *, first: bool) -> tuple[str, dict[str, str]]:
    """What changed, in words, and what each answer letter (besides skip) would do."""
    label = f"{KINDS[item.kind]} {item.key}"
    if item.kind == "file" and item.target is None:
        # Newly listed. No discard: a file is never deleted from the machine.
        return f"{label}: listed, but not saved in the repo yet", {"k": "eep (save it to the repo)"}
    if item.target is None:
        options = {"k": "eep (add to the list)", "d": "iscard (remove from this machine)"}
        if item.kind in ("package", "webapp"):
            options["i"] = "gnore (never sync it)"
        return f"{label}: on this machine, not in the list", options
    if item.machine is None:
        changed = ", changed in the list" if item.status == "conflict" else ""
        options = {"k": "eep (remove from the list)", "d": "iscard (put it back here)"}
        return f"{label}: in the list, not on this machine{changed}", options
    if first:
        what = "differs from the list"
    elif item.status == "conflict":
        what = "changed on this machine and in the list"
    else:
        what = "changed on this machine"
    options = {"k": "eep (save this machine's to the list)", "d": "iscard (use the list's here)"}
    return f"{label}: {what}", options


def _detail(item: Item) -> str:
    """The two versions of a changed item: a diff for files, the values for everything else."""
    if item.target is None or item.machine is None:
        return ""
    if item.kind != "file":
        return f"  list: {item.target}\n  here: {item.machine}"
    versions = (item.target.splitlines(), item.machine.splitlines())
    lines = [f"  {line}" for line in difflib.unified_diff(*versions, "list", "this machine", lineterm="")]
    if len(lines) > DIFF_LINES:
        lines = [*lines[:DIFF_LINES], f"  ... ({len(lines) - DIFF_LINES} more lines)"]
    return "\n".join(lines)


def _choose(prompt: str, options: str, default: str) -> str:
    """Prompt until the answer is one of the single-letter `options`."""
    while (choice := typer.prompt(prompt, default=default)) not in tuple(options):
        typer.echo(f"Enter one of: {', '.join(options)}.")
    return choice


def _ask_all(pending: list[Item], *, first: bool) -> None:
    """Fill in `choice` for every local change / conflict."""
    where = "difference(s) between this machine and the list" if first else "change(s) on this machine, not in the list"
    typer.echo(f"\n{len(pending)} {where}:")
    # A fresh machine can have dozens of new packages; offer one answer for the lot. "Discard
    # all" (uninstall) is easy to regret, so it lists them again and asks to confirm.
    for kind in ("package", "webapp"):
        group = [item for item in pending if item.kind == kind and item.target is None]
        if len(group) > BULK_THRESHOLD:
            typer.echo(f"\n{len(group)} of them are {KINDS[kind]}s on this machine but not in the list:")
            typer.echo(f"  {', '.join(item.key for item in group)}")
            menu = ", ".join(
                [
                    "[e]ach",
                    "[k]eep all (add to the list)",
                    "[d]iscard all (remove from this machine)",
                    "[i]gnore all (never sync)",
                    "[s]kip all",
                ]
            )
            choice = _choose(menu, "ekdis", "e")
            if choice == "d":
                names = "\n".join(f"  {item.key}" for item in group)
                if not typer.confirm(f"Remove these {len(group)} {KINDS[kind]}s from this machine?\n{names}\n"):
                    choice = "e"
            for item in group if choice != "e" else []:
                item.choice = choice
    # Same for a machine that has never synced and differs in many places (a new laptop).
    differing = [item for item in pending if item.target is not None and item.machine is not None]
    if first and len(differing) > BULK_THRESHOLD:
        typer.echo(f"\n{len(differing)} of them differ from the list (this machine has not synced before):")
        typer.echo(f"  {', '.join(f'{KINDS[item.kind]} {item.key}' for item in differing)}")
        choice = _choose("[e]ach, [d]iscard all (use the list's here; files are backed up), [s]kip all", "eds", "e")
        for item in differing if choice != "e" else []:
            item.choice = choice
    for item in pending:
        if item.choice:
            continue
        text, options = _question(item, first=first)
        typer.echo(f"\n{text}")
        if detail := _detail(item):
            typer.echo(detail)
        menu = ", ".join([*(f"[{letter}]{rest}" for letter, rest in options.items()), "[s]kip"])
        item.choice = _choose(menu, "".join([*options, "s"]), "s")


def _preview(pending: list[Item], incoming: list[Item], target: dict[str, Any], *, first: bool) -> None:
    """Dry run: print what `sync` would ask and change."""
    if pending:
        typer.echo("\nWould ask about (changes on this machine that are not in the list):")
        for item in pending:
            typer.echo(f"  {_question(item, first=first)[0]}")
            if detail := _detail(item):
                typer.echo(detail)
    hook = [] if _has_bashrc_hook() else ["add `source .os/rc` to ~/.bashrc (the `os` alias)"]
    plan = [*(_plan_line(item, target) for item in incoming), *hook]
    if plan:
        typer.echo("\nWould change this machine (from the list):")
        for line in plan:
            typer.echo(f"  {line}")
    if not pending and not plan:
        typer.echo("This machine matches the list.")
    status = _out(["git", "-C", str(REPO), "status", "--short", "--", ".os"])
    if status:
        typer.echo(f"\nWould commit (.os/ only):\n{status}")


def _table(doc: tomlkit.TOMLDocument, name: str) -> Any:
    if name not in doc:
        doc[name] = tomlkit.table()
    return doc[name]


def _put(table: Any, key: str, value: Any) -> None:
    """Set `table[key]`, keeping a new key above the blank line that ends the table."""
    if key in table:
        table[key] = value
        return
    body = table.value.body
    blank_lines = 0
    while body and body[-1][0] is None and isinstance(body[-1][1], Whitespace):
        body.pop()
        blank_lines += 1
    table[key] = value
    for _ in range(blank_lines):
        table.add(tomlkit.nl())


def _array_add(table: Any, key: str, value: str) -> None:
    if key not in table:
        table[key] = tomlkit.array()
    array = table[key]
    if value in array:
        return
    if "\n" in array.as_string():
        array.add_line(value)  # keeps the one-per-line layout and its comments
    else:
        array.append(value)
        array.multiline(len(array) == 1)


def _save_all(kept: list[Item]) -> None:
    """Write the kept / ignored changes into .os/ (the list and the tracked files)."""
    doc = tomlkit.parse(MACHINE_LIST.read_text())
    foreign = set(_out(["pacman", "-Qqm"]).split())
    for item in kept:
        if item.choice == "i":
            _array_add(_table(doc, "ignore"), "packages" if item.kind == "package" else "webapps", item.key)
        elif item.kind == "package":
            packages = _table(doc, "packages")
            for repo in ("pacman", "aur"):
                if item.key in packages.get(repo, []):
                    packages[repo].remove(item.key)
            if item.machine:
                _array_add(packages, "aur" if item.key in foreign else "pacman", item.key)
        elif item.kind == "file":
            _save_file(_table(doc, "files"), item)
        else:
            table = _table(doc, TABLES[item.kind])
            if item.machine is None:
                del table[item.key]
            else:
                _put(table, item.key, json.loads(item.machine) if item.kind == "bar" else item.machine)
    MACHINE_LIST.write_text(tomlkit.dumps(doc))


def _save_file(files: Any, item: Item) -> None:
    if item.machine is None:
        del files[item.key]
        (FILES / item.key).unlink(missing_ok=True)
        return
    if item.key not in files:
        _put(files, item.key, "always")  # newly tracked (through `os save`)
    (FILES / item.key).parent.mkdir(parents=True, exist_ok=True)
    shutil.copy(HOME / item.key, FILES / item.key)


def _plan_line(item: Item, target: dict[str, Any]) -> str:
    """One line of the "will change this machine" plan."""
    if item.kind == "package":
        aur = " (AUR)" if item.key in target.get("packages", {}).get("aur", []) else ""
        return f"install package {item.key}{aur}" if item.target else f"remove package {item.key}"
    if item.kind in ("plugin", "webapp"):
        action = "remove" if item.target is None else "update" if item.machine else "install"
        return f"{action} {KINDS[item.kind]} {item.key}"
    if item.kind == "file":
        return f"write file ~/{item.key}{' (the current one is backed up)' if item.machine else ''}"
    if item.kind == "toggle":
        return f"turn {item.target} toggle {item.key}"
    return f"set {'bar option ' if item.kind == 'bar' else ''}{item.key} to {item.target}"


def _commands(item: Item) -> list[list[str]]:
    """The Omarchy commands that make this machine match the list (not packages or files)."""
    if item.kind == "plugin":
        remove = [["omarchy", "plugin", "remove", item.key, "--yes"]] if item.machine else []
        add = [["omarchy", "plugin", "add", item.target, "--enable", "--yes"]] if item.target else []
        return [*remove, *add]
    if item.kind == "webapp":
        if item.target is None:
            return [["omarchy", "webapp", "remove", item.key]]
        # No icon given: Omarchy fetches the site's own.
        return [["omarchy", "webapp", "install", item.key, item.target, ""]]
    if item.kind in ("setting", "toggle"):
        command = SETTINGS[item.key][1] if item.kind == "setting" else [*TOGGLE, item.key]
        return [[*command, item.target or ""]]
    widget_id, _, option = item.key.rpartition(".")
    value = json.loads(item.target or "null")
    if isinstance(value, str):
        return [["omarchy", "bar", "set", widget_id, option, value]]
    return [["omarchy", "bar", "set", widget_id, option, json.dumps(value), "--json"]]


def _write_file(path: str) -> bool:
    """Copy a tracked file from the repo onto this machine, backing up what it replaces."""
    source, destination = FILES / path, HOME / path
    if not source.is_file():
        return False
    if destination.exists():
        backup = STATE / "backup" / RUN_STAMP / path
        backup.parent.mkdir(parents=True, exist_ok=True)
        shutil.copy2(destination, backup)
    destination.parent.mkdir(parents=True, exist_ok=True)
    shutil.copy(source, destination)
    typer.echo(f"wrote ~/{path}")
    return True


def _has_bashrc_hook() -> bool:
    return BASHRC.is_file() and BASHRC_LINE in BASHRC.read_text().splitlines()


def _apply_confirmed(changes: list[Item], target: dict[str, Any], *, yes: bool) -> tuple[bool, list[str]]:
    """Show the plan, confirm, apply. Returns (applied, plan lines that failed)."""
    hook = not _has_bashrc_hook()
    if not changes and not hook:
        typer.echo("\nNothing to change on this machine.")
        return True, []
    typer.echo("\nWill change this machine:")
    for item in changes:
        typer.echo(f"  {_plan_line(item, target)}")
    if hook:
        typer.echo("  add `source .os/rc` to ~/.bashrc (the `os` alias)")
    if not yes and not typer.confirm("Apply?"):
        typer.echo("Not applied; the next `os sync` offers these again.")
        return False, []
    failed = _apply(changes, target)
    if hook:
        with BASHRC.open("a") as bashrc:
            bashrc.write(f"\n{BASHRC_LINE}\n")
    return True, failed


def _apply(changes: list[Item], target: dict[str, Any]) -> list[str]:
    """Make this machine match the list for each change; returns the plan lines that failed."""
    failed = []
    aur = set(target.get("packages", {}).get("aur", []))
    installs = [item for item in changes if item.kind == "package" and item.target]
    batches = [
        (["omarchy", "pkg", "add"], [item for item in installs if item.key not in aur]),
        (["omarchy", "pkg", "aur", "add"], [item for item in installs if item.key in aur]),
        (["omarchy", "pkg", "drop"], [item for item in changes if item.kind == "package" and not item.target]),
    ]
    for command, packages in batches:
        if not packages or _run([*command, *(item.key for item in packages)]):
            continue
        # One bad name fails the whole batch; go one at a time to find which.
        alone = len(packages) == 1
        failed += [_plan_line(item, target) for item in packages if alone or not _run([*command, item.key])]
    for item in changes:
        if item.kind == "package":
            continue
        done = _write_file(item.key) if item.kind == "file" else all(_run(cmd) for cmd in _commands(item))
        if not done:
            failed.append(_plan_line(item, target))
    return failed


def _commit_and_push(message: str, *, push: bool, yes: bool) -> bool:
    """Commit .os/ (only .os/) and push. Returns False only when a push was rejected."""
    git = ["git", "-C", str(REPO)]
    status = _out([*git, "status", "--short", "--", ".os"])
    # A push sends every unpushed commit on the branch, not just this one; show them up front.
    log = subprocess.run([*git, "log", "--oneline", "@{u}..HEAD"], capture_output=True, text=True, check=False)
    unpushed = log.stdout.strip() if push else ""
    if not status and not unpushed:
        typer.echo("\nNothing to commit.")
        return True
    if status:
        typer.echo(f"\nWill commit (.os/ only; other changes stay out):\n{status}")
    if unpushed:
        typer.echo(f"\nUnpushed commits that a push would also send:\n{unpushed}")
    if yes:
        push = push and not unpushed  # never push other commits unattended
    else:
        steps = [*(["commit"] if status else []), *([f"push{' all' if unpushed else ''}"] if push else [])]
        if not typer.confirm(f"\n{' and '.join(steps).capitalize()}?"):
            typer.echo("Left as is; the next `os sync` offers this again.")
            return True

    if status:
        commit = [*git, "commit", "-m", message, "--", ".os"]
        subprocess.run([*git, "add", "--", ".os"], check=True)
        # Pre-commit hooks may auto-fix files (eg JSON formatting) and fail once; restage,
        # retry.
        if subprocess.run(commit, check=False).returncode != 0:
            subprocess.run([*git, "add", "--", ".os"], check=True)
            subprocess.run(commit, check=True)
    if not push:
        typer.echo("Not pushed; the next `os sync` offers to push.")
    elif subprocess.run([*git, "push"], check=False).returncode != 0:
        typer.echo("Push rejected (remote likely ahead); run `git pull --rebase`, then `git push`.", err=True)
        return False
    return True


def _stored_password() -> bytes | None:
    """The 1Password master password from gnome-keyring, or None if none is stored."""
    result = subprocess.run(["secret-tool", "lookup", *KEYRING_ATTRS], capture_output=True, check=False)
    return result.stdout if result.returncode == 0 and result.stdout else None


def _offer_pwd_store() -> None:
    """During sync: offer `pwd-store` when this machine's keyring has no password yet."""
    if shutil.which("secret-tool") is None:
        typer.echo("\nsecret-tool missing (libsecret); run `os pwd-store` once it is installed.", err=True)
        return
    if _stored_password() is not None:
        return
    if typer.confirm("\nNo 1Password master password in the keyring yet. Store it now?", default=True):
        pwd_store()
    else:
        typer.echo("Skipped; `os pwd-store` stores it later (the next `os sync` asks again).")


@app.command()
def pwd_store() -> None:
    """Save the 1Password master password in gnome-keyring (prompted, never an arg)."""
    password: str = typer.prompt("1Password master password", hide_input=True, confirmation_prompt=True)
    subprocess.run(
        ["secret-tool", "store", "--label=1Password master password", *KEYRING_ATTRS],
        input=password.encode(),
        check=True,
    )
    typer.echo("Stored in gnome-keyring.")


@app.command()
def pwd_copy() -> None:
    """Copy the stored 1Password master password to the clipboard."""
    password = _stored_password()
    if password is None:
        typer.echo("No password found in gnome-keyring; run `pwd-store` first.", err=True)
        raise typer.Exit(1)
    subprocess.run(["wl-copy", "--type", "text/plain"], input=password, check=True)
    # Detached so the clear still happens after this CLI exits.
    subprocess.Popen(
        ["sh", "-c", f"sleep {CLEAR_AFTER_SECONDS} && wl-copy --clear"],
        start_new_session=True,
        stdout=subprocess.DEVNULL,
        stderr=subprocess.DEVNULL,
    )
    typer.echo(f"Copied to clipboard; clearing in {CLEAR_AFTER_SECONDS}s.")


if __name__ == "__main__":
    app()
